import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  FiMessageCircle, FiUsers, FiCalendar, FiTrendingUp, FiHeart, FiShield,
  FiPlus, FiSearch, FiBell, FiClock, FiStar, FiArrowRight, FiActivity,
  FiZap, FiTarget, FiAward, FiChevronRight, FiUser, FiMail, FiPhone
} from 'react-icons/fi';
import { getChatList } from '../../store/slices/chatSlice';
import { getDoctors } from '../../store/slices/userSlice';
import LoadingSpinner from '../../components/UI/LoadingSpinner';

const Dashboard = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { user } = useSelector((state) => state.auth);
  const { chats = [], isLoading: chatLoading } = useSelector((state) => state.chat || {});
  const { doctors = [], isLoading: doctorLoading } = useSelector((state) => state.user || {});
  
  const [recentActivity, setRecentActivity] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    console.log('Dashboard: Loading chats and doctors...');
    // Load user's chats
    dispatch(getChatList({ page: 1, limit: 10 }));
    
    // Load recent doctors
    dispatch(getDoctors({ page: 1, limit: 6 }));
    
    // Generate mock recent activity (replace with real data later)
    setRecentActivity([
      { id: 1, type: 'message', message: 'New message from Dr. Smith', time: '2 minutes ago', icon: FiMessageCircle },
      { id: 2, type: 'appointment', message: 'Appointment reminder for tomorrow', time: '1 hour ago', icon: FiCalendar },
      { id: 3, type: 'file', message: 'Lab report uploaded', time: '3 hours ago', icon: FiShield },
    ]);
    
    // Generate mock notifications
    setNotifications([
      { id: 1, type: 'info', message: 'Welcome to Remutre! Start your health journey today.', time: 'Just now', unread: true },
      { id: 2, type: 'success', message: 'Your chat with Dr. Johnson is now active', time: '5 minutes ago', unread: true },
    ]);
  }, [dispatch]);

  useEffect(() => {
    console.log('Dashboard: Chats updated:', chats);
    console.log('Dashboard: Chat loading state:', chatLoading);
  }, [chats, chatLoading]);

  const handleChatClick = (chat) => {
    console.log('Dashboard: Chat clicked:', chat);
    const chatId = chat.id || chat._id;
    navigate(`/chat/${chatId}`);
  };

  // Calculate real statistics
  const activeChats = chats.filter(chat => chat.lastMessage && new Date(chat.lastMessage.createdAt) > new Date(Date.now() - 24 * 60 * 60 * 1000)).length;
  const availableDoctors = doctors.filter(doctor => doctor.isActive !== false).length;
  const totalConsultations = chats.length; // Total chats as consultations
  const healthScore = Math.min(100, Math.max(60, 75 + (chats.length * 2) + (availableDoctors > 0 ? 10 : 0))); // Dynamic health score

  const stats = [
    {
      name: 'Active Chats',
      value: activeChats,
      total: chats.length,
      icon: FiMessageCircle,
      color: 'text-blue-600',
      bgColor: 'bg-gradient-to-br from-blue-50 to-blue-100',
      gradient: 'from-blue-500 to-blue-600',
      description: `${chats.length} total conversations`
    },
    {
      name: 'Available Doctors',
      value: availableDoctors,
      icon: FiUsers,
      color: 'text-green-600',
      bgColor: 'bg-gradient-to-br from-green-50 to-green-100',
      gradient: 'from-green-500 to-green-600',
      description: 'Ready to help you'
    },
    {
      name: 'Total Consultations',
      value: totalConsultations,
      icon: FiCalendar,
      color: 'text-purple-600',
      bgColor: 'bg-gradient-to-br from-purple-50 to-purple-100',
      gradient: 'from-purple-500 to-purple-600',
      description: 'Health sessions completed'
    },
    {
      name: 'Health Score',
      value: `${healthScore}%`,
      icon: FiTrendingUp,
      color: 'text-orange-600',
      bgColor: 'bg-gradient-to-br from-orange-50 to-orange-100',
      gradient: 'from-orange-500 to-orange-600',
      description: 'Based on your activity'
    },
  ];

  const features = [
    {
      title: 'Instant Messaging',
      description: 'Chat with doctors and health professionals in real-time',
      icon: FiMessageCircle,
      color: 'text-blue-600',
      bgColor: 'bg-blue-50',
    },
    {
      title: 'File Sharing',
      description: 'Share medical reports, images, and documents securely',
      icon: FiShield,
      color: 'text-green-600',
      bgColor: 'bg-green-50',
    },
    {
      title: 'Health Tracking',
      description: 'Monitor your health journey and track progress',
      icon: FiHeart,
      color: 'text-red-600',
      bgColor: 'bg-red-50',
    },
  ];

  return (
    <div className="dashboard-container space-y-6">
      {/* Welcome Section */}
      <div className="bg-gradient-to-r from-primary-600 to-health-600 rounded-xl p-4 text-white">
        <h1 className="text-2xl font-bold mb-2">
          Welcome back, {user?.fullName?.split(' ')[0] || 'User'}! 👋
        </h1>
        <p className="text-primary-100">
          Ready to take care of your health? Connect with doctors and manage your wellness journey.
        </p>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {stats.map((stat, index) => {
          const Icon = stat.icon;
          return (
            <div key={stat.name} className="bg-white rounded-lg p-4 shadow-sm border border-gray-200">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-gray-600">{stat.name}</p>
                  <p className="text-2xl font-bold text-gray-900 mt-1">{stat.value}</p>
                </div>
                <div className={`p-3 rounded-lg ${stat.bgColor}`}>
                  <Icon className={`h-6 w-6 ${stat.color}`} />
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Recent Chats */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200">
          <div className="p-4 border-b border-gray-200">
            <h2 className="text-lg font-semibold text-gray-900">Recent Chats</h2>
          </div>
          <div className="p-4">
            {chatLoading ? (
              <div className="flex items-center justify-center py-8">
                <LoadingSpinner />
              </div>
            ) : chats.length > 0 ? (
              <div className="space-y-4">
                {chats.slice(0, 3).map((chat) => {
                  const otherParticipant = chat?.participants?.find(p => {
                    const participantId = p.id || p._id;
                    const currentUserId = user?.id || user?._id;
                    return participantId !== currentUserId;
                  });
                  
                  return (
                  <div key={chat._id} className="flex items-center space-x-3 p-3 rounded-lg hover:bg-gray-50 cursor-pointer" onClick={() => handleChatClick(chat)}>
                    <div className="w-10 h-10 bg-gradient-to-r from-primary-500 to-health-500 rounded-full flex items-center justify-center">
                      <span className="text-white font-medium text-sm">
                        {(otherParticipant?.fullName || otherParticipant?.name || otherParticipant?.displayName)?.charAt(0)?.toUpperCase() || 'U'}
                      </span>
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium text-gray-900 truncate">
                        {otherParticipant?.fullName || otherParticipant?.name || otherParticipant?.displayName || 'Unknown User'}
                      </p>
                      <p className="text-xs text-gray-500 truncate">
                        {chat.lastMessage?.content || 'No messages yet'}
                      </p>
                    </div>
                    <div className="text-xs text-gray-400">
                      {chat.lastMessage?.createdAt ? 
                        new Date(chat.lastMessage.createdAt).toLocaleDateString() : 
                        'New'
                      }
                    </div>
                  </div>
                  );
                })}
              </div>
            ) : (
              <div className="text-center py-8">
                <FiMessageCircle className="mx-auto h-12 w-12 text-gray-400" />
                <p className="mt-2 text-sm text-gray-500">No chats yet</p>
                <p className="text-xs text-gray-400">Start a conversation with a doctor</p>
              </div>
            )}
          </div>
        </div>

        {/* Available Doctors */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200">
          <div className="p-4 border-b border-gray-200">
            <h2 className="text-lg font-semibold text-gray-900">Available Doctors</h2>
          </div>
          <div className="p-4">
            {doctorLoading ? (
              <div className="flex items-center justify-center py-8">
                <LoadingSpinner />
              </div>
            ) : doctors.length > 0 ? (
              <div className="space-y-4">
                {doctors.slice(0, 3).map((doctor) => (
                  <div key={doctor._id} className="flex items-center space-x-3 p-3 rounded-lg hover:bg-gray-50 cursor-pointer">
                    <div className="w-10 h-10 bg-gradient-to-r from-green-500 to-health-500 rounded-full flex items-center justify-center">
                      <span className="text-white font-medium text-sm">
                        {doctor.fullName?.charAt(0)?.toUpperCase() || 'D'}
                      </span>
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium text-gray-900 truncate">
                        Dr. {doctor.fullName}
                      </p>
                      <p className="text-xs text-gray-500 truncate">
                        {doctor.specialization}
                      </p>
                    </div>
                    <div className="text-xs text-green-600 font-medium">
                      ₹{doctor.consultationFee}
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-8">
                <FiUsers className="mx-auto h-12 w-12 text-gray-400" />
                <p className="mt-2 text-sm text-gray-500">No doctors available</p>
                <p className="text-xs text-gray-400">Check back later</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Features Section */}
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Why Choose Health Chat?</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {features.map((feature, index) => {
            const Icon = feature.icon;
            return (
              <div key={feature.title} className="text-center">
                <div className={`w-16 h-16 ${feature.bgColor} rounded-full flex items-center justify-center mx-auto mb-4`}>
                  <Icon className={`h-8 w-8 ${feature.color}`} />
                </div>
                <h3 className="text-lg font-medium text-gray-900 mb-2">{feature.title}</h3>
                <p className="text-sm text-gray-600">{feature.description}</p>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
